```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Server' AND span_name LIKE 'GET%' GROUP BY ALL ORDER BY n DESC",
          "claim": "In the incident, train-service receives 473 GET /error requests returning 403, and no trains/byName GET calls are seen from travel-plan."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code, count(*) n FROM normal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "In normal operation train-service never serves GET /error; it serves GET trains/byName with 200 responses."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name cspan, c.attr_http_response_status_code cstatus, s.span_name sspan, s.attr_http_response_status_code sstatus, count(*) n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Every travel-plan GET client call to train-service returns 403 and maps to a callee GET /error span, 473 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan's quickest, minStation and cheapest endpoints return 500 errors in the incident, matching the 403 failures from train."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-plan-service' AND level='SEVERE' GROUP BY ALL",
          "claim": "Travel-plan logs 473 SEVERE HttpClientErrorException Forbidden exceptions from its train-service call."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY n DESC",
          "claim": "ui-dashboard's travelPlan endpoints return 500 with multi-second p95 latency, inheriting the travel-plan failures."
        }
      ]
    }
  ]
}
